"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines


def _is_include(line):
    parts = line.split(None, 1)
    return bool(parts) and parts[0] == "@include"


def _expand(path, stack, is_include):
    real = os.path.realpath(path)
    if real in stack:
        raise ConfigError("include cycle detected at: {}".format(path))
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError as exc:
        if not is_include:
            raise
        raise ConfigError("cannot read include file {}: {}".format(path, exc))
    stack = stack + (real,)
    base = os.path.dirname(real)
    out = []
    for line in lines:
        if not _is_include(line):
            out.append(line)
            continue
        parts = line.split(None, 1)
        if len(parts) < 2:
            raise ConfigError("@include requires a path in {}".format(path))
        target = os.path.join(base, parts[1].strip())
        out.extend(_expand(target, stack, True))
    return out


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced inline by the contents of the
    referenced file, resolved relative to the including file.
    """
    return parse_lines(_expand(os.fspath(path), (), False))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
